const D = { energy:.6, scale:1, density:.5, speed:1, hue:96, x:.42, y:.5, teeth:.5, anno:.7, style:'film', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const T2 = Math.PI*2;
const cl = (v,a,b) => v<a?a:(v>b?b:v);
const lp = (a,b,s) => a+(b-a)*s;
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const AL = cl(P.alpha,20,100)/100;
const H = ((P.hue%360)+360)%360;
const sty = P.style;
const anno = cl(P.anno,0,1);
const NRG = cl(P.energy,0,1);

// ---- palette per style -------------------------------------------------------
function pal(){
  if (sty==='cyanotype') return { g:[212,72,19], body:[210,60,29], line:[200,6,99], ctr:[196,34,84], pitch:[190,42,76], anno:[200,10,92], hatch:[205,48,60], grain:36, add:false, wash:[196,20,80] };
  if (sty==='engraving') return { g:[38,17,73],  body:[36,13,60], line:[28,36,12], ctr:[8,64,40],  pitch:[30,32,28], anno:[28,40,15], hatch:[30,30,24], grain:32, add:false, wash:[44,26,96] };
  if (sty==='xray')      return { g:[228,58,10], body:[H,62,24],  line:[H,26,97], ctr:[12,74,60],  pitch:[168,58,72], anno:[H,14,86], hatch:[H,42,52], grain:18, add:true,  wash:[H,42,66] };
  if (sty==='schematic') return { g:[196,36,9],  body:[196,44,15], line:[178,64,92], ctr:[10,72,70], pitch:[178,72,86], anno:[52,56,88], hatch:[186,42,42], grain:14, add:false, wash:[184,40,60] };
  return { g:[H,15,21], body:[H,11,33], line:[H,4,93], ctr:[10,68,64], pitch:[H,24,70], anno:[H,6,88], hatch:[H,9,56], grain:28, add:false, wash:[H,10,80] };
}
const C = pal();
const sc = (c,a) => { stroke(c[0], c[1], c[2], a*AL); };
const fc = (c,a) => { fill(c[0], c[1], c[2], a*AL); };

// ---- real-time drive: monotonic accumulator + section gear-shift --------------
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
const secN = K.section|0;
let tgt = fr(secN*3.77 + 11)*1.75 - .62;
if (Math.abs(tgt) < .38) tgt = tgt < 0 ? -.38 : .38;
tgt *= (.5 + .8*K.intensity);
if (S.rate == null) S.rate = tgt;
S.rate += (tgt - S.rate) * cl(dt*1.1, 0, 1);
const wob = 1 + .26*Math.sin(K.t*.131) + .17*Math.sin(K.t*.313+1.1) + .09*Math.sin(K.t*.767+2.3);
S.th = (S.th||0) + dt * S.rate * wob * P.speed * (1.0 + 1.9*NRG);
const ths = S.th;

// ---- incommensurate plate drift + breathe (motion floor, no audio needed) -----
const drx = .9*Math.sin(K.t*.137) + .5*Math.sin(K.t*.293+1.7) + .32*Math.sin(K.t*.451);
const dry = .8*Math.sin(K.t*.109+2.1) + .45*Math.sin(K.t*.257+.6) + .28*Math.sin(K.t*.617+1.9);
const zm = 1 + .045*NRG*(Math.sin(K.t*.089) + .6*Math.sin(K.t*.211+1.3));
S.bs = (S.bs||0)*.84 + (A.bass||0)*.16;
const glow = (.45 + .55*NRG)*(.55 + .5*K.intensity) + S.bs*.3;

// ---- involute-ish tooth profile, cached per tooth count -----------------------
S.prof = S.prof || {};
function profile(Z, internal){
  const kk = Z + (internal ? 'i' : 'e');
  if (S.prof[kk]) return S.prof[kk];
  const ht = Math.PI/(2*Z);
  const ra = internal ? 1 - 2/Z   : 1 + 2/Z;
  const rf = internal ? 1 + 2.5/Z : 1 - 2.5/Z;
  const pts = [];
  for (let k=0;k<Z;k++){
    const a0 = k*T2/Z;
    pts.push([rf,a0-ht*1.30],[1,a0-ht*1.00],[ra,a0-ht*.55],[ra,a0+ht*.55],[1,a0+ht*1.00],[rf,a0+ht*1.30]);
  }
  S.prof[kk] = pts; return pts;
}
function toothPath(cx,cy,rp,Z,ang,internal,rev){
  const pts = profile(Z, internal);
  if (rev) { for (let i=pts.length-1;i>=0;i--){ const a=pts[i][1]+ang, r=pts[i][0]*rp; vertex(cx+Math.cos(a)*r, cy+Math.sin(a)*r); } }
  else     { for (let i=0;i<pts.length;i++){ const a=pts[i][1]+ang, r=pts[i][0]*rp; vertex(cx+Math.cos(a)*r, cy+Math.sin(a)*r); } }
}

// ---- epicyclic sets that actually close: Zr = Zs+2Zp, (Zs+Zr)/np integer ------
const COMBOS = [[18,15,48,3],[24,18,60,4],[20,16,52,4],[30,15,60,3],[16,20,56,4],[24,12,48,6],[36,12,60,4]];
const cb = COMBOS[Math.floor(fr(7.3)*COMBOS.length) % COMBOS.length];
const Zs=cb[0], Zp=cb[1], Zr=cb[2], np=cb[3];
const mod = (.54*u*P.scale)/Zr * zm;
const rs = mod*Zs/2, rpl = mod*Zp/2, rr = mod*Zr/2;
const Rout = rr*(1+2.5/Zr) + mod*1.6;
const ex = cl(P.x,.12,.88)*width  + u*.024*NRG*drx;
const ey = cl(P.y,.12,.88)*height + u*.020*NRG*dry;

// kinematics: ring fixed, sun input, carrier output
const kr = Zs/(Zs+Zr);
const thc = ths*kr;
const b0 = thc;
const thp0 = b0 + Math.PI + Math.PI/Zp - (Zs/Zp)*(ths - b0);
const thr = b0 + Math.PI/Zr + (Zp/Zr)*(thp0 - b0);
const ratio = 1 + Zr/Zs;

// ---- spur chain: each mesh solved from the previous -> geometrically exact ----
const ckey = sd+'|'+cl(P.teeth,0,1).toFixed(3)+'|'+Math.round(P.density*24)+'|'+Math.round(P.scale*80)+'|'+width+'x'+height;
if (S.ck !== ckey){
  S.ck = ckey;
  const Zlo = Math.round(lp(11,17,cl(P.teeth,0,1))), Zhi = Math.round(lp(19,36,cl(P.teeth,0,1)));
  const nch = Math.round(3 + cl(P.density,0,1)*8);
  const ch = [];
  const Z0 = Math.round(lp(Zlo,Zhi,fr(11.7)));
  let bp = -1e9, sx=0, sy=0, sphi=0;
  for (let c=0;c<20;c++){
    const ph = fr(3.1)*T2 + c*T2/20;
    const dd = Rout + mod*Z0/2 + u*.055;
    const nx = ex + Math.cos(ph)*dd, ny = ey + Math.sin(ph)*dd;
    const mg = mod*(Z0/2+1) + u*.03;
    const s = Math.min(nx-mg, width-mg-nx, ny-mg, height-mg-ny);
    if (s > bp){ bp = s; sx = nx; sy = ny; sphi = ph; }
  }
  ch.push({ x:sx, y:sy, Z:Z0, rp:mod*Z0/2, rt:mod*(Z0/2+1), ph:fr(19.1)*T2, drv:0 });
  let prevB = sphi;
  for (let i=1;i<nch;i++){
    const g0 = ch[i-1];
    const Zn = Math.round(lp(Zlo,Zhi,fr(i*5.77+2.3)));
    const rn = mod*Zn/2, rtn = mod*(Zn/2+1);
    const cd = g0.rp + rn;
    let bb = null, bs = -1e18;
    for (let c=0;c<18;c++){
      const b = prevB + (c/17-.5)*2.6 + (fr(i*9.1+c*.37)-.5)*.5;
      const nx = g0.x + Math.cos(b)*cd, ny = g0.y + Math.sin(b)*cd;
      let s = 0;
      const mg = rtn + u*.028;
      if (nx<mg || nx>width-mg || ny<mg || ny>height-mg) s -= 1400;
      s -= 26*Math.abs(((b-prevB+Math.PI)%T2+T2)%T2 - Math.PI);
      const dr = Math.hypot(nx-ex, ny-ey), needr = rtn + Rout + u*.018;
      if (dr < needr) s -= (needr-dr)*14;
      for (let j=0;j<i-1;j++){ const gg=ch[j], dd2=Math.hypot(nx-gg.x, ny-gg.y), need=rtn+gg.rt+u*.014; if (dd2<need) s -= (need-dd2)*11; }
      if (s > bs){ bs = s; bb = b; }
    }
    if (bs < -600) break;
    ch.push({ x:g0.x+Math.cos(bb)*cd, y:g0.y+Math.sin(bb)*cd, Z:Zn, rp:rn, rt:rtn, b:bb, drv:1 });
    prevB = bb;
  }
  S.chain = ch;
}
const chain = S.chain || [];
// resolve chain angles by the external-mesh phase law
chain[0] && (chain[0].ang = thc + chain[0].ph);
for (let i=1;i<chain.length;i++){
  const a=chain[i-1], b=chain[i];
  b.ang = b.b + Math.PI + Math.PI/b.Z - (a.Z/b.Z)*(a.ang - b.b);
}

// ---- cached plate texture ----------------------------------------------------
const gkey = sd+'|'+sty+'|'+width+'x'+height;
if (!S.gr || S.gkey !== gkey){
  if (S.gr && S.gr.remove) S.gr.remove();
  const gw=170, gh=Math.max(60, Math.round(170*height/Math.max(1,width)));
  const g = createGraphics(gw,gh);
  g.loadPixels();
  for (let y=0;y<gh;y++) for (let x=0;x<gw;x++){
    const c1 = fr(Math.floor(x/9)*13.71 + Math.floor(y/9)*7.33 + 3.1);
    const c2 = fr(Math.floor(x/3)*3.17 + Math.floor(y/3)*11.9 + 8.7);
    const c3 = fr(x*1.13 + y*3.31 + 1.7);
    const v = cl(255*(.42 + .34*c1 + .17*c2 + .07*c3), 0, 255);
    const j = (y*gw+x)*4; g.pixels[j]=v; g.pixels[j+1]=v; g.pixels[j+2]=v; g.pixels[j+3]=255;
  }
  g.updatePixels();
  S.gr = g; S.gkey = gkey;
}

// ---- ground + texture + drafting grid ---------------------------------------
noStroke(); fill(C.g[0], C.g[1], C.g[2], 100); rect(0,0,width,height);
push(); blendMode(MULTIPLY); tint(0,0,100,C.grain); image(S.gr, 0,0, width,height); pop();
blendMode(BLEND); noTint();
const gs = u*.055;
sc(C.hatch, 9*AL + 7*anno); strokeWeight(Math.max(.5,u*.0009));
for (let x=(-drx*u*.01)%gs; x<width; x+=gs) line(x,0,x,height);
for (let y=(-dry*u*.01)%gs; y<height; y+=gs) line(0,y,width,y);

// ---- wandering inspection wash (big soft light, SCREEN) -----------------------
const wx = width*(.5 + .30*Math.sin(K.t*.071) + .13*Math.sin(K.t*.181+2.2));
const wy = height*(.5 + .26*Math.sin(K.t*.097+1.1) + .11*Math.sin(K.t*.233+.4));
push(); blendMode(SCREEN); noStroke();
for (let i=5;i>=1;i--){ const rw = u*(.34+i*.20); fill(C.wash[0], C.wash[1], C.wash[2], (2.2 + 2.0*glow)*AL); ellipse(wx, wy, rw*2, rw*2*.82); }
pop(); blendMode(BLEND);

// ---- helpers -----------------------------------------------------------------
function dashdot(x0,y0,x1,y1,w){
  const L = Math.hypot(x1-x0,y1-y0); if (L<1) return;
  const ux=(x1-x0)/L, uy=(y1-y0)/L; const per=w*9;
  sc(C.ctr, 46+24*anno); strokeWeight(Math.max(.5,w*.34));
  for (let s=0;s<L;s+=per){
    const a=s, b=Math.min(L,s+per*.62); line(x0+ux*a,y0+uy*a,x0+ux*b,y0+uy*b);
    const c=Math.min(L,s+per*.78), d2=Math.min(L,s+per*.86); line(x0+ux*c,y0+uy*c,x0+ux*d2,y0+uy*d2);
  }
}
function chainCircle(cx,cy,r){
  sc(C.pitch, 30+34*anno); strokeWeight(Math.max(.5,u*.0011)); noFill();
  const n = Math.max(24, Math.round(r*.5));
  for (let i=0;i<n;i++){ if (i%3===2) continue; const a0=i/n*T2, a1=(i+.72)/n*T2;
    line(cx+Math.cos(a0)*r, cy+Math.sin(a0)*r, cx+Math.cos(a1)*r, cy+Math.sin(a1)*r); }
}
function crossMark(cx,cy,r){ sc(C.ctr, 70); strokeWeight(Math.max(.6,u*.0013)); line(cx-r,cy,cx+r,cy); line(cx,cy-r,cx,cy+r); }
function hatchDisc(cx,cy,r0,r1,ang,n){
  sc(C.hatch, 40+16*anno); strokeWeight(Math.max(.4,u*.0008));
  const st = (r1-r0)/n;
  for (let i=0;i<n;i++){ const rr2=r0+st*(i+.5); const a0=ang+i*.11;
    line(cx+Math.cos(a0)*rr2, cy+Math.sin(a0)*rr2, cx+Math.cos(a0+2.4)*rr2, cy+Math.sin(a0+2.4)*rr2); }
}

// ---- SCHEMATIC style: gears abstracted to pitch circles + velocity vectors ----
const schem = (sty==='schematic');
if (C.add) blendMode(ADD);

function drawGear(cx,cy,rp,Z,ang,spin){
  if (schem){
    chainCircle(cx,cy,rp); crossMark(cx,cy,rp*.16);
    // pitch-point velocity vector — magnitude ~ omega*r
    const vv = cl(spin*rp*.30, -rp*.9, rp*.9);
    sc([340,72,90], 78); strokeWeight(Math.max(.7,u*.0016));
    const ax=cx+rp, ay=cy; line(ax,ay,ax,ay-vv);
    const dsn = vv<0?-1:1; line(ax,ay-vv, ax-rp*.05, ay-vv+dsn*rp*.09); line(ax,ay-vv, ax+rp*.05, ay-vv+dsn*rp*.09);
    return;
  }
  noStroke(); fc(C.body, C.add ? 26 : 92);
  beginShape(); toothPath(cx,cy,rp,Z,ang,false,false); endShape(CLOSE);
  hatchDisc(cx,cy,rp*.30,rp*.86, ang*.4 + cx*.01, Math.max(3, Math.round(rp/(u*.014))));
  noFill(); sc(C.line, (C.add ? 62+30*glow : 88)); strokeWeight(Math.max(.6, u*.0016*(.7+.6*NRG)));
  beginShape(); toothPath(cx,cy,rp,Z,ang,false,false); endShape(CLOSE);
  // hub + bore + spokes
  fc(C.g, C.add?18:88); noStroke(); ellipse(cx,cy, rp*.42, rp*.42);
  sc(C.line, 74); noFill(); strokeWeight(Math.max(.5,u*.0012));
  ellipse(cx,cy, rp*.42, rp*.42); ellipse(cx,cy, rp*.17, rp*.17);
  const nsp = rp > u*.055 ? 6 : 3;
  for (let i=0;i<nsp;i++){ const a=ang*1 + i*T2/nsp; line(cx+Math.cos(a)*rp*.21, cy+Math.sin(a)*rp*.21, cx+Math.cos(a)*rp*.62, cy+Math.sin(a)*rp*.62); }
  crossMark(cx,cy,rp*.20);
}

// ---- ring gear (internal) ----------------------------------------------------
if (!schem){
  noStroke(); fc(C.body, C.add?22:88);
  beginShape();
  for (let i=0;i<72;i++){ const a=i/72*T2; vertex(ex+Math.cos(a)*Rout, ey+Math.sin(a)*Rout); }
  beginContour(); toothPath(ex,ey,rr,Zr,thr,true,true); endContour();
  endShape(CLOSE);
  noFill(); sc(C.line, C.add?58+28*glow:86); strokeWeight(Math.max(.6,u*.0016*(.7+.6*NRG)));
  ellipse(ex,ey,Rout*2,Rout*2);
  beginShape(); toothPath(ex,ey,rr,Zr,thr,true,false); endShape(CLOSE);
  // housing lugs
  for (let i=0;i<4;i++){ const a=i*T2/4 + .4; const lx=ex+Math.cos(a)*Rout, ly=ey+Math.sin(a)*Rout;
    noStroke(); fc(C.body, C.add?24:90); ellipse(lx,ly, mod*3.0, mod*3.0);
    noFill(); sc(C.line,80); strokeWeight(Math.max(.5,u*.0012)); ellipse(lx,ly, mod*3.0, mod*3.0); ellipse(lx,ly, mod*1.1, mod*1.1); }
} else { chainCircle(ex,ey,rr); chainCircle(ex,ey,Rout); }
if (anno>.1) chainCircle(ex,ey,rr);

// ---- carrier arms (section-hatched) ------------------------------------------
if (!schem){
  for (let i=0;i<np;i++){
    const bi = thc + i*T2/np;
    push(); translate(ex,ey); rotate(bi);
    noStroke(); fc(C.body, C.add?18:74);
    rect(0, -mod*1.05, rs+rpl, mod*2.1, mod*.8);
    sc(C.line, 66); noFill(); strokeWeight(Math.max(.5,u*.0011));
    rect(0, -mod*1.05, rs+rpl, mod*2.1, mod*.8);
    sc(C.hatch, 44); strokeWeight(Math.max(.4,u*.0007));
    for (let h=0; h<rs+rpl; h+=mod*.75) line(h, -mod*1.05, h+mod*2.1, mod*1.05);
    pop();
  }
}

// ---- sun + planets -----------------------------------------------------------
for (let i=0;i<np;i++){
  const bi = thc + i*T2/np;
  const px = ex + Math.cos(bi)*(rs+rpl), py = ey + Math.sin(bi)*(rs+rpl);
  const thp = bi + Math.PI + Math.PI/Zp - (Zs/Zp)*(ths - bi);
  drawGear(px,py,rpl,Zp,thp, -S.rate*(Zs/Zp));
  if (anno>.35) dashdot(ex,ey,px,py, u*.0018);
}
drawGear(ex,ey,rs,Zs,ths, S.rate);

// ---- spur chain --------------------------------------------------------------
for (let i=0;i<chain.length;i++){
  const g = chain[i];
  drawGear(g.x,g.y,g.rp,g.Z,g.ang, (i%2? -1:1)*S.rate*.7);
  if (anno>.2) chainCircle(g.x,g.y,g.rp);
  if (i>0 && anno>.45) dashdot(chain[i-1].x, chain[i-1].y, g.x, g.y, u*.0016);
}
// coupling from carrier to chain input
if (chain.length){
  const g = chain[0];
  dashdot(ex,ey,g.x,g.y,u*.0022);
  const mx=(ex+g.x)/2, my=(ey+g.y)/2, ca=Math.atan2(g.y-ey,g.x-ex);
  push(); translate(mx,my); rotate(ca);
  noStroke(); fc(C.body, C.add?26:92); rect(-mod*1.1,-mod*1.5, mod*2.2, mod*3.0);
  noFill(); sc(C.line,84); strokeWeight(Math.max(.5,u*.0013)); rect(-mod*1.1,-mod*1.5, mod*2.2, mod*3.0);
  line(0,-mod*1.5,0,mod*1.5);
  pop();
}

blendMode(BLEND);

// ---- plate furniture: sheet border, title block, annotations ------------------
const mgn = u*.030;
noFill(); sc(C.line, 52+22*anno); strokeWeight(Math.max(.8,u*.0022));
rect(mgn, mgn, width-mgn*2, height-mgn*2);
sc(C.line, 30+18*anno); strokeWeight(Math.max(.5,u*.0010));
rect(mgn*1.6, mgn*1.6, width-mgn*3.2, height-mgn*3.2);

if (anno > .08){
  textFont('monospace'); textAlign(LEFT, CENTER);
  const ts = Math.max(7, u*.0135);
  textSize(ts); noStroke();
  fc(C.anno, 66+30*anno);
  const lab = (s,x,y) => text(s, x, y);
  lab('Z'+Zr+'  RING (FIXED)', ex - Rout*.72, ey - Rout - u*.016);
  lab('Z'+Zs+'  SUN / INPUT', ex + rs*.5, ey + rs + u*.026);
  lab('Z'+Zp+' x'+np+'  PLANET', ex + Rout*.30, ey + Rout*.62);
  textAlign(RIGHT, CENTER);
  const bx = width-mgn*1.9, by = height-mgn*1.9;
  fc(C.body, C.add?30:80); noStroke(); rect(bx-u*.30, by-u*.075, u*.30, u*.075);
  noFill(); sc(C.line, 66); strokeWeight(Math.max(.5,u*.0012)); rect(bx-u*.30, by-u*.075, u*.30, u*.075);
  line(bx-u*.30, by-u*.048, bx, by-u*.048); line(bx-u*.30, by-u*.024, bx, by-u*.024);
  noStroke(); fc(C.anno, 88);
  text('EPICYCLIC REDUCTION UNIT', bx-u*.012, by-u*.061);
  text('i = 1 + Z'+Zr+'/Z'+Zs+' = '+ratio.toFixed(3)+' : 1', bx-u*.012, by-u*.036);
  text('MODULE m='+(mod/ (u*.006)).toFixed(2)+'   SHT 1/1   SEED '+sd, bx-u*.012, by-u*.012);
  textAlign(LEFT, CENTER);
  for (let i=0;i<chain.length;i++){ const g=chain[i];
    fc(C.anno, 48+34*anno); text('Z'+g.Z, g.x + g.rt*.72, g.y - g.rt*.72); }
  // live shaft-speed readout — genuinely changes frame to frame
  fc(C.anno, 70);
  textAlign(LEFT, CENTER);
  text('n1 '+(S.rate*60).toFixed(1)+' rpm', mgn*2.1, mgn*2.4);
  text('nc '+(S.rate*kr*60).toFixed(2)+' rpm', mgn*2.1, mgn*2.4 + ts*1.5);
  text('thS '+(((ths*57.2958)%360+360)%360).toFixed(1)+' deg', mgn*2.1, mgn*2.4 + ts*3.0);
}

blendMode(BLEND); noTint(); drawingContext.shadowBlur = 0;
